using System.Text.Json;
using CondoManager.Application;
using CondoManager.Domain;
namespace CondoManager.UnitTests;
public class VotingEngineTests
{
 private readonly VotingEngine engine=new();
 private static VotingCriteria Rule(VotingPurpose purpose=VotingPurpose.Deliberative,MeetingCall call=MeetingCall.First,VotingDenominator heads=VotingDenominator.Present,VotingDenominator value=VotingDenominator.Building,long numerator=1,long denominator=2)=>new(purpose,call,null,new(1,2,heads,ThresholdComparison.GreaterThan),new(numerator,denominator,value,ThresholdComparison.AtLeast),"Synthetic criterion","Synthetic explicitly reviewed scope");
 private static VotingElectorate Plate(params decimal[] values)=>new(Guid.NewGuid(),DateTimeOffset.UtcNow,1000,values.Select((v,i)=>new ElectoralRight("H"+i,Guid.NewGuid(),"Synthetic "+i,Guid.NewGuid(),"Synthetic actor",[Guid.NewGuid()],v,true)).ToArray(),[],[],"Synthetic manual review","synthetic");
 private static CastBallot[] Choices(params BallotChoice[] choices)=>choices.Select((c,i)=>new CastBallot("H"+i,c)).ToArray();
 [Theory][InlineData(MeetingCall.First)][InlineData(MeetingCall.Second)]public void ConstitutionalRulesAreIndependentPerCall(MeetingCall call){var rule=VotingRuleTemplates.All().Single(t=>t.Code=="CC1136-CONST-"+(call==MeetingCall.First?"1":"2")).Criteria;var all=Plate(400,300,300);Assert.Equal(VoteOutcome.Approved,engine.Evaluate(rule,all,[]).Outcome);var one=all with{Rights=all.Rights.Select((r,i)=>r with{IsPresent=i==0}).ToArray()};Assert.Equal(call==MeetingCall.First?VoteOutcome.Rejected:VoteOutcome.Approved,engine.Evaluate(rule,one,[]).Outcome);}
 [Fact]public void NumericalMajorityDoesNotReplaceMillesimalMajority(){var p=Plate(70,70,70,70,160,160);var result=engine.Evaluate(Rule(),p,Choices(BallotChoice.InFavor,BallotChoice.InFavor,BallotChoice.InFavor,BallotChoice.InFavor,BallotChoice.Against,BallotChoice.Against));Assert.True(result.Heads.Satisfied);Assert.False(result.Value.Satisfied);Assert.Equal(280,result.Totals.InFavorValue);Assert.Equal(VoteOutcome.Rejected,result.Outcome);}
 [Fact]public void MillesimalMajorityDoesNotReplaceHeadcount(){var result=engine.Evaluate(Rule(),Plate(800,100,100),Choices(BallotChoice.InFavor,BallotChoice.Against,BallotChoice.Against));Assert.False(result.Heads.Satisfied);Assert.True(result.Value.Satisfied);Assert.Equal(VoteOutcome.Rejected,result.Outcome);}
 [Theory][InlineData("500",true)][InlineData("499.999999",false)][InlineData("500.000001",true)]public void ExactBoundaryHasNoFloatingPointRounding(string value,bool expected){Assert.Equal(expected,VotingEngine.Meets(decimal.Parse(value,System.Globalization.CultureInfo.InvariantCulture),1000,new(1,2,VotingDenominator.Building,ThresholdComparison.AtLeast)));}
 [Theory][InlineData("333.333333",false)][InlineData("333.333334",true)]public void OneThirdIsNotRoundedToSixDecimals(string value,bool expected){Assert.Equal(expected,VotingEngine.Meets(decimal.Parse(value,System.Globalization.CultureInfo.InvariantCulture),1000,new(1,3,VotingDenominator.Building,ThresholdComparison.AtLeast)));}
 [Fact]public void AbstentionsDependOnDenominator(){var plate=Plate(100,100,100,100,100,100,100,100,100,100);var votes=Choices(BallotChoice.InFavor,BallotChoice.InFavor,BallotChoice.InFavor,BallotChoice.InFavor,BallotChoice.InFavor,BallotChoice.Against,BallotChoice.Against,BallotChoice.Against,BallotChoice.Abstained,BallotChoice.Abstained);Assert.Equal(VoteOutcome.Rejected,engine.Evaluate(Rule(),plate,votes).Outcome);Assert.Equal(VoteOutcome.Approved,engine.Evaluate(Rule(heads:VotingDenominator.Expressed),plate,votes).Outcome);}
 [Fact]public void PresentNonVotersAreDistinctFromAbstentionsAndAbsentees(){var plate=Plate(400,300,200,100);plate=plate with{Rights=plate.Rights.Select((r,i)=>r with{IsPresent=i!=3}).ToArray()};var result=engine.Evaluate(Rule(),plate,Choices(BallotChoice.InFavor,BallotChoice.Abstained));Assert.Equal(1,result.Totals.NonVoting);Assert.Equal(1,result.Totals.Abstained);Assert.Equal(1,result.Totals.Absent);Assert.Equal(200,result.Totals.NonVotingValue);Assert.Equal(100,result.Totals.AbsentValue);}
 [Theory][InlineData(true)][InlineData(false)]public void UnanimousAndAdverseVotes(bool yes){var result=engine.Evaluate(Rule(),Plate(500,300,200),Choices(yes?BallotChoice.InFavor:BallotChoice.Against,yes?BallotChoice.InFavor:BallotChoice.Against,yes?BallotChoice.InFavor:BallotChoice.Against));Assert.Equal(yes?VoteOutcome.Approved:VoteOutcome.Rejected,result.Outcome);}
 [Fact]public void AnomalousRepresentationIsUndetermined(){var plate=Plate(500,500) with{Anomalies=["Unresolved joint ownership"]};Assert.Equal(VoteOutcome.Undetermined,engine.Evaluate(Rule(),plate,Choices(BallotChoice.InFavor,BallotChoice.InFavor)).Outcome);}
 [Fact]public void DuplicateBallotOrForeignRightCannotApprove(){var plate=Plate(1000);Assert.Equal(VoteOutcome.Undetermined,engine.Evaluate(Rule(),plate,[new("H0",BallotChoice.InFavor),new("H0",BallotChoice.InFavor)]).Outcome);Assert.Equal(VoteOutcome.Undetermined,engine.Evaluate(Rule(),plate,[new("FOREIGN",BallotChoice.InFavor)]).Outcome);}
 [Fact]public void DuplicateUnitCannotBeCounted(){var p=Plate(500,500);p=p with{Rights=[p.Rights[0],p.Rights[1] with{PropertyUnitIds=p.Rights[0].PropertyUnitIds}]};Assert.Equal(VoteOutcome.Undetermined,engine.Evaluate(Rule(),p,Choices(BallotChoice.InFavor,BallotChoice.InFavor)).Outcome);}
 [Fact]public void DelegateCanCastDifferentChoicesForDistinctPrincipals(){var p=Plate(120,880);var actor=Guid.NewGuid();p=p with{Rights=p.Rights.Select(r=>r with{ExpressedById=actor}).ToArray()};var result=engine.Evaluate(Rule(),p,Choices(BallotChoice.InFavor,BallotChoice.Against));Assert.Equal(2,result.Totals.Present);Assert.Equal(120,result.Totals.InFavorValue);Assert.Equal(880,result.Totals.AgainstValue);}
 [Fact]public void MultipleUnitsForOneHeadRetainOneVote(){var p=Plate(1000);p=p with{Rights=[p.Rights[0] with{PropertyUnitIds=[Guid.NewGuid(),Guid.NewGuid()]}]};var result=engine.Evaluate(Rule(),p,Choices(BallotChoice.InFavor));Assert.Equal(1,result.Totals.InFavor);Assert.Equal(1000,result.Totals.InFavorValue);}
 [Fact]public void ZeroDenominatorIsUndetermined(){Assert.Equal(VoteOutcome.Undetermined,engine.Evaluate(Rule(heads:VotingDenominator.Expressed),Plate(1000),[]).Outcome);}
 [Fact]public void CalculationIsDeterministicAndSideEffectFree(){var p=Plate(500,300,200);var choices=Choices(BallotChoice.InFavor,BallotChoice.InFavor,BallotChoice.Against);var json=JsonSerializer.Serialize(p);Assert.Equal(JsonSerializer.Serialize(engine.Evaluate(Rule(),p,choices)),JsonSerializer.Serialize(engine.Evaluate(Rule(),p,choices)));Assert.Equal(json,JsonSerializer.Serialize(p));}
 [Fact]public void InvalidFractionsAndUndefinedCriteriaAreRejected(){Assert.Throws<ArgumentException>(()=>(Rule() with{Heads=new(1,0,VotingDenominator.Present,ThresholdComparison.AtLeast)}).Validate());Assert.Throws<ArgumentException>(()=>(Rule(VotingPurpose.Constitutive) with{Heads=new(1,2,VotingDenominator.Expressed,ThresholdComparison.AtLeast)}).Validate());}
}
